from fastapi import FastAPI, APIRouter, FastAPIError

def test_router_include_self():
    router = APIRouter()
    try:
        router.include_router(router)
        print("Successfully included router into itself (should have failed)")
    except Exception as e:
        print(f"Caught expected exception: {type(e).__name__}: {e}")

def test_app_include_self():
    app = FastAPI()
    try:
        app.include_router(app) # type: ignore
        print("Successfully included app into itself (should have failed)")
    except Exception as e:
        print(f"Caught expected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_router_include_self()
    test_app_include_self()
